    func checkpoint(){dirty=true;undo.append(project);if undo.count>20{undo.removeFirst()};redo=[]}
    func replaceProject(_ p:Project){for key in project.patterns.keys where p.patterns[key]==nil{for t in 0..<24{for s in 0..<128{push(key,t,s,Cell())}}};project=p;clampTrack();row=min(row,pattern.length-1);songRow=min(songRow,max(0,song.count-1));anchor=nil;sync()}
    func history(_ back:Bool){if back,let p=undo.popLast(){redo.append(project);replaceProject(p)}else if !back,let p=redo.popLast(){undo.append(project);replaceProject(p)}}
    func changePattern(_ p:Pattern){checkpoint();pattern=p;clampTrack();row=min(row,p.length-1);anchor=nil;sync()}
    func requireRec()->Bool{if rec{return true};message="Press R to enable REC (red editing mode).";return false}
    func insertNotes(_ notes:[Int],_ label:String=""){guard track<activeTrackCount else{message="Press Enter on Add Track";return};let ins=cell.instrument ?? trackDefaults[track];guard ins>=0 else{message="No instrument: press I, Enter and choose one first";return};if !requireRec(){tm_preview(packed(notes),Int32(ins));return};if liveRec&&playing&&Int(tm_step())>=0{if !armed.isEmpty && !armed.contains(track){message="Track is not armed";return};row=min(pattern.length-1,Int(tm_step()))};var c=cell;c.notes=notes;c.duration=nil;c.noteOff=nil;c.label=label;c.harmonicRoot=notes.count>1 ? notes.first:nil;c.instrument=ins;cell=c;tm_preview(packed(notes),Int32(ins));if !liveRec{row=min(pattern.length-1,row+project.step)};anchor=nil;needsDisplay=true}
    func beginEdit(){if let f=footer{if f != 0 && !requireRec(){return};modal=3;modalField=f;editValue=[project.selected,pattern.length,project.step][f];return};if addTrackSelected{expandTracks();return};if field==1{modal=2;modalField=1;editValue=max(0,cell.instrument ?? trackDefaults[track]);return};if !requireRec(){return};if field==0{if cell.instrument==nil&&trackDefaults[track]<0{field=1;beginEdit();message="Choose an instrument first";return};modal=1;noteTab=cell.notes.count>1 ? 1:0;if let n=cell.notes.first{root=n%12;octave=max(0,n/12-1);if let i=chords.firstIndex(where:{$0.1==cell.notes.map{$0-n}}){chordIndex=i}};return};modal=2;modalField=field;let c=cell;switch field{case 2:editValue=c.velocity ?? 100;case 3:editValue=c.volume ?? 100;case 4:editValue=c.pan ?? 0;case 5:editFX=c.fx ?? 0;editFXValue=c.fxValue ?? 50;case 6:editFX=c.fx2 ?? 0;editFXValue=c.fx2Value ?? 50;default:editValue=c.micro ?? 0}}
    func adjustFooter(_ f:Int,_ value:Int){if f != 0 && !requireRec(){return};anchor=nil;switch f{case 0:project.selected=max(0,min(127,value));if project.patterns[project.selected]==nil{project.patterns[project.selected]=Pattern()};row=0;scroll=0;clampTrack();tm_select_pattern(Int32(project.selected),Int32(pattern.length));case 1:checkpoint();var p=pattern;p.length=max(1,min(128,value));pattern=p;row=min(row,p.length-1);tm_select_pattern(Int32(project.selected),Int32(p.length));default:project.step=max(0,min(16,value));dirty=true};syncSong()}
    func adjustModal(_ d:Int){if modal==4{tempoEdit=max(40,min(800,tempoEdit+Double(d)));return};if modal==3{if softHeld != nil{softChanged=true};let lo=modalField==1 ? 1:0,hi=modalField==0 ? 127:modalField==1 ? 128:16;editValue=max(lo,min(hi,editValue+d))}else if modalField==5||modalField==6{editFXValue=max(editFX==7 ? 1:0,min(editFX==7 ? 48:100,editFXValue+d))}else if modalField==7{editValue=max(0,min(75,editValue+(d>0 ? 25:-25)))}else{let lo=modalField==4 ? -50:0,hi=modalField==1 ? 47:modalField==4 ? 50:100;editValue=max(lo,min(hi,editValue+d))}}
    func commit(){if modal==2 && (modalField==5||modalField==6) && editFX==8{openStepEQ();return};if modal==4{if let n=Double(tempoInput),!tempoInput.isEmpty{setTempo(n)}else{setTempo(tempoEdit)}}else if modal==1{let base=(octave+1)*12+root;if noteTab==0{insertNotes([min(127,base)])}else{let c=chords[chordIndex],suffix=c.0=="Major" ? "":c.0=="Minor" ? "m":c.0,b=min(base,127-(c.1.last ?? 0));insertNotes(c.1.map{b+$0},"\(names[b%12])\(suffix)-\(b/12-1)")}}else if modal==3{adjustFooter(modalField,editValue)}else{if modalField==1{guard slots[editValue].name != "EMPTY" else{message="Empty slot: add a sample in Sample Loader (8)";modal=0;return};if trackDefaults[track]<0{assignInstrument(editValue,wholeTrack:false)}else if requireRec(){var c=cell;c.instrument=editValue;cell=c};modal=0;return};var c=cell;switch modalField{case 2:c.velocity=editValue;case 3:c.volume=editValue;case 4:c.pan=editValue;case 5:c.fx=editFX;c.fxValue=editFXValue;c.eq1=nil;case 6:c.fx2=editFX;c.fx2Value=editFXValue;c.eq2=nil;default:c.micro=editValue};cell=c};modal=0}
