    func rename(_ trackName:Bool){let a=NSAlert();a.messageText=trackName ? "Track Name":"Pattern Name";a.addButton(withTitle:"Apply");a.addButton(withTitle:"Cancel");let input=NSTextField(frame:NSRect(x:0,y:0,width:300,height:24));input.stringValue=trackName ? trackNames[track]:(pattern.name ?? "Pattern \(project.selected)");a.accessoryView=input;a.window.initialFirstResponder=input;if a.runModal() == .alertFirstButtonReturn{checkpoint();if trackName{var ns=trackNames;ns[track]=String(input.stringValue.prefix(24));project.trackNames=ns}else{var p=pattern;p.name=String(input.stringValue.prefix(32));pattern=p;message="Pattern: \(p.name ?? "")"}};held.removeAll()}
    func tapTempo(){let now=Date.timeIntervalSinceReferenceDate;if let last=taps.last,now-last>2{taps=[]};taps.append(now);if taps.count>4{taps.removeFirst()};if taps.count==4{setTempo(60/max(0.075,(taps.last!-taps.first!)/3))};message="Tap tempo: \(taps.count)/4  \(bpmLabel) BPM"}
    func mute(_ t:Int,solo:Bool=false){let id=mixScopeID;var p=project.patterns[id] ?? Pattern();guard (0..<p.activeTrackCount).contains(t) else{return};checkpoint();var m=Set(p.trackMutes ?? project.trackMutes ?? []),s=Set(p.trackSolos ?? project.trackSolos ?? []);if solo{if s.contains(t){s.remove(t)}else{s.insert(t)};p.trackSolos=s.sorted()}else{if m.contains(t){m.remove(t)}else{m.insert(t)};p.trackMutes=m.sorted()};project.patterns[id]=p;tm_pattern_mute_mask(Int32(id),maskFor(m,s));needsDisplay=true}
    func previewCell(){guard !addTrackSelected else{return};let c=cell;let ins=c.instrument ?? trackDefaults[track];if ins>=0{tm_preview(packed(c.notes.isEmpty ? [(octave+1)*12]:c.notes),Int32(ins))}else{message="Choose an instrument first"}}
