    func pasteSteps(_ only:Int?=nil){guard !addTrackSelected,requireRec(),!clip.isEmpty else{return};var p=pattern;for (ti,a) in clip.enumerated() where track+ti<p.activeTrackCount{for (ri,c) in a.enumerated() where row+ri<p.length{if let f=only{var dest=p.cells[track+ti][row+ri];switch f{case 0,1:dest.notes=c.notes;dest.noteOff=c.noteOff;dest.label=c.label;dest.harmonicRoot=c.harmonicRoot;dest.instrument=c.instrument;case 5:dest.fx=c.fx;dest.fxValue=c.fxValue;dest.eq1=c.eq1;case 6:dest.fx2=c.fx2;dest.fx2Value=c.fx2Value;dest.eq2=c.eq2;default:break};p.cells[track+ti][row+ri]=dest}else{p.cells[track+ti][row+ri]=c}}};changePattern(p);message="Pasted selection"}
