    func resizePattern(_ mode:Int){guard requireRec() else{return};let old=pattern;var p=old;if mode==2{p.length=max(1,old.length/2);for t in 0..<24{for i in 0..<p.length{p.cells[t][i]=old.cells[t][i*2]};for i in p.length..<128{p.cells[t][i]=Cell()}}}else{p.length=min(128,old.length*2);if mode==0{for t in 0..<24{for r in old.length..<p.length{p.cells[t][r]=old.cells[t][r%old.length]}}}else{for t in 0..<24{for r in 0..<p.length{p.cells[t][r]=r%2==0 ? old.cells[t][r/2]:Cell()}}}};changePattern(p)}
    func soft(_ i:Int,shift:Bool){if page==12{omSoft(i);return};if page==10 && !shift{recorderSoft(i);return};if page==11 && !shift{fxSoft(i);return};if page==6 && !shift{if i==7{selectPage(0)}else if i==4{tm_dsp_reset();message="DSP statistics reset"}else{midiConfigSoft(i)};return};if samplePage{sampleSoft(i);return};if page==3 && !shift{mixerSoft(i);return};if shift{let t=(page==3 ? mixerBank:firstTrack)+i;guard t<(page==3 ? mixerTrackCount:activeTrackCount) else{return};if held.contains(15){if armed.contains(t){armed.remove(t)}else{armed.insert(t)};message="Armed: \(armed.sorted().map{String($0+1)}.joined(separator:", "))"}else{mute(t,solo:page==3)};return};if page==0{if i==7{more=(more+1)%3;footer=nil;return};if more==0{switch i{case 0...2:footer=i;beginEdit();case 3:fill();case 4:previewCell();case 5:history(true);case 6:history(false);default:break}}else if more==1{switch i{case 0:exportAudio(patternOnly:true);case 1:invert();case 2:resizePattern(0);case 3:resizePattern(1);case 4:resizePattern(2);case 5:patternClip=pattern;message="Pattern copied";case 6:pastePattern();default:break}}else{if i==0{rename(false)}else if i==1{rename(true)}else if i==2{openDuration()}}}else if page==1{switch i{case 0:message="Q/E selects pattern in REC";case 1:insertSong();case 2:deleteSong();case 3:exportAudio();case 4:togglePlay();case 5:history(true);case 6:history(false);case 7:tapTempo();default:break}}else if page==5{switch i{case 0:homeAction("New");case 1:load();case 4:save();case 5:save(true);case 7:home=true;homeSelection=0;default:break}}else if page==7{switch i{case 0,4:importSample();case 3:openRecorder();case 1:importSample(true);case 2:if slots[instrumentRow].name != "EMPTY"{tm_preview(packed([slots[instrumentRow].root]),Int32(instrumentRow))};case 7:selectPage(0);default:break}}else if page==2{switch i{case 0:assignInstrument(instrumentRow,wholeTrack:true);case 1:changeWave(-1);case 2:changeWave(1);case 3:if slots[instrumentRow].name != "EMPTY"{tm_preview(packed([s